{
  "aggregate_id": "DEF-NRS-484A-305::truck",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "The contract describes a human-powered device, which the quoted vehicle exception removes from the motor vehicles required by the truck definition."
    },
    {
      "class": "ru.bus",
      "verdict": "contradicted",
      "reason": "Design to carry many passengers does not preclude the stated goods use and purpose-built body, and every bus satisfying those conditions meets the included ru.truck contract."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person rather than the motor vehicle required by the quoted admitting words."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "supported",
      "reason": "Every commercial-class member admitted by the goods-use and purpose-built-body requirements satisfies the ru.truck contract, whereas mass class or licensing alone does not establish those requirements."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "The quoted motor-vehicle exception expressly removes electric bicycles from the motor vehicles required by the truck definition."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "The quoted motor-vehicle exception expressly removes electric scooters from the motor vehicles required by the truck definition."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "contradicted",
      "reason": "Emergency designation does not prohibit the stated goods use or purpose-built body, and every member satisfying the truck requirements meets the included ru.truck contract."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "contradicted",
      "reason": "A fire-fighting vehicle is not barred from meeting the goods-use and purpose-built-body requirements, and every member meeting them satisfies the included ru.truck contract."
    },
    {
      "class": "ru.moped",
      "verdict": "contradicted",
      "reason": "The quoted wheel restriction does not prohibit goods use or a body built for that purpose, and every moped satisfying the truck requirements meets the included ru.truck contract."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "Every member admitted by the additional goods-use and purpose-built-body requirements satisfies the ru.truck contract, while self-propulsion alone does not establish those requirements."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "contradicted",
      "reason": "The wheel count and astride-riding contract do not preclude a purpose-built goods body and goods use, and every qualifying member meets the included ru.truck contract."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "Every official-service member satisfying the quoted motor-vehicle, goods-use and purpose-built-body requirements meets the ru.truck contract, while official service alone does not establish those requirements."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The contract describes a person on foot, in a wheelchair or treated as on foot, not the motor vehicle required by the truck definition."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person with specified assistance rather than the motor vehicle required by the quoted admitting words."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "supported",
      "reason": "The contract describes on-track equipment, whereas the quoted motor-vehicle definition requires a vehicle not operated upon rails."
    },
    {
      "class": "ru.school_bus",
      "verdict": "contradicted",
      "reason": "Designation and markings for carrying school children do not prohibit the stated goods use and purpose-built body, and every qualifying member meets the included ru.truck contract."
    },
    {
      "class": "ru.taxicab",
      "verdict": "contradicted",
      "reason": "The passenger-for-hire contract does not prohibit goods use or a body also built for that purpose, and every member satisfying the truck requirements meets the included ru.truck contract."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "contradicted",
      "reason": "The tour, shuttle or lengthened-passenger-vehicle contract does not prohibit the stated goods use and purpose-built body, and every qualifying member meets the included ru.truck contract."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "supported",
      "reason": "Any member admitted by the quoted motor-vehicle, goods-use and purpose-built-body requirements necessarily satisfies the ru.truck contract."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "contradicted",
      "reason": "Public transit service does not prohibit the stated goods use or purpose-built body, and every member satisfying the truck requirements meets the included ru.truck contract."
    },
    {
      "class": "ru.truck",
      "verdict": "supported",
      "reason": "The quoted admitting clause matches the contract's motor vehicle for carrying goods with a body built for that purpose, and no posted exception removes that class."
    }
  ]
}

